/* ============================================================================
 * DNN Primitives: Batch Normalization Wrappers (Section 13.4)
 * ========================================================================= */

/* Batch Normalization - Training Forward Pass */
void fb_batch_norm_forward_training_from_unified(
    const size_t *dims, size_t ndims, const void *input, void *output,
    const void *scale, const void *bias, void *running_mean, void *running_var,
    float momentum, float epsilon) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  vtable->normalize_unified(
      FB_NORM_BATCH,        /* mode */
      FB_NORM_TRAINING,     /* phase */
      dims, ndims, NULL, 0, /* normalize_axes (auto-selected for batch norm) */
      input, output, scale, bias, running_mean, running_var, momentum, epsilon,
      0,                     /* num_groups (not used for batch norm) */
      0.0f, 1.0f,            /* scale_min, scale_max (not used) */
      NULL, NULL, NULL, NULL /* gradients (not used in forward pass) */
  );
}

/* Batch Normalization - Inference Forward Pass */
void fb_batch_norm_forward_inference_from_unified(
    const size_t *dims, size_t ndims, const void *input, void *output,
    const void *scale, const void *bias, const void *running_mean,
    const void *running_var, float epsilon) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  vtable->normalize_unified(
      FB_NORM_BATCH, FB_NORM_INFERENCE, /* inference mode */
      dims, ndims, NULL, 0, input, output, scale, bias, running_mean,
      running_var, 0.0f, epsilon, /* momentum not used in inference */
      0, 0.0f, 1.0f, NULL, NULL, NULL, NULL);
}

/* Batch Normalization - Backward Pass */
void fb_batch_norm_backward_from_unified(
    const size_t *dims, size_t ndims, const void *input,
    const void *grad_output, void *grad_input, void *grad_scale,
    void *grad_bias, const void *scale, const void *running_mean,
    const void *running_var, float epsilon) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  vtable->normalize_unified(
      FB_NORM_BATCH, FB_NORM_TRAINING,   /* backward pass uses training mode */
      dims, ndims, NULL, 0, input, NULL, /* output not needed for backward */
      scale, NULL,                       /* bias not needed for backward */
      running_mean, running_var, 0.0f, epsilon, 0, 0.0f, 1.0f, grad_output,
      grad_input, grad_scale, grad_bias);
}

/* Layer Normalization - Forward Pass */
void fb_layer_norm_forward_from_unified(const size_t *dims, size_t ndims,
                                        const void *input, void *output,
                                        const void *scale, const void *bias,
                                        float epsilon) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  vtable->normalize_unified(
      FB_NORM_LAYER,
      FB_NORM_TRAINING,     /* layer norm doesn't distinguish train/inference */
      dims, ndims, NULL, 0, /* normalize over last dimension(s) by default */
      input, output, scale, bias, NULL, NULL, /* no running statistics */
      0.0f, epsilon, 0, 0.0f, 1.0f, NULL, NULL, NULL, NULL);
}

