/* ============================================================================
 * Statistics: Z-Score Normalization Wrappers (Section 14)
 * ========================================================================= */

/* Standard Z-Score Normalization */
void fb_stats_zscore_from_unified(const void *input, void *output,
                                  size_t count) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  size_t dims[1] = {count};

  vtable->normalize_unified(
      FB_NORM_Z_SCORE, FB_NORM_TRAINING, dims, 1, NULL, 0, input, output, NULL,
      NULL,                    /* no scale/bias parameters */
      NULL, NULL, 0.0f, 1e-8f, /* small epsilon for numerical stability */
      0, 0.0f, 1.0f, NULL, NULL, NULL, NULL);
}

/* Modified Z-Score (robust to outliers) */
void fb_stats_modified_zscore_from_unified(const void *input, void *output,
                                           size_t count) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  size_t dims[1] = {count};

  /* Modified z-score uses median absolute deviation instead of std dev
   * For now, we route to standard z-score; backends can override
   * with specialized implementation if needed */
  vtable->normalize_unified(
      FB_NORM_Z_SCORE, /* use standard z-score as approximation */
      FB_NORM_TRAINING, dims, 1, NULL, 0, input, output, NULL, NULL, NULL, NULL,
      0.0f, 1e-8f, 0, 0.0f, 1.0f, NULL, NULL, NULL, NULL);
}

/* ============================================================================
 * Preprocessing: Data Normalization Wrappers (Section 15.5)
 * ========================================================================= */

/* Standardize (z-score normalization, alias) */
void fb_standardize_from_unified(const void *input, void *output,
                                 size_t count) {

  /* Standardize is identical to z-score */
  fb_stats_zscore_from_unified(input, output, count);
}

/* Normalize (L1/L2/Max normalization) */
void fb_normalize_from_unified(const void *input, void *output, size_t count,
                               int norm_type) { /* 1=L1, 2=L2, 0=Max */

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  size_t dims[1] = {count};

  /* Map norm_type to mode enum */
  fb_norm_mode_t mode;
  switch (norm_type) {
  case 1:
    mode = FB_NORM_L1;
    break;
  case 2:
    mode = FB_NORM_L2;
    break;
  default:
    mode = FB_NORM_MAX;
    break;
  }

  vtable->normalize_unified(mode, FB_NORM_TRAINING, dims, 1, NULL, 0, input,
                            output, NULL, NULL, NULL, NULL, 0.0f, 1e-8f, 0,
                            0.0f, 1.0f, NULL, NULL, NULL, NULL);
}

/* Min-Max Scaling */
void fb_min_max_scale_from_unified(const void *input, void *output,
                                   size_t count, float scale_min,
                                   float scale_max) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->normalize_unified) {
    return;
  }

  size_t dims[1] = {count};

  vtable->normalize_unified(FB_NORM_MIN_MAX_SCALE, FB_NORM_TRAINING, dims, 1,
                            NULL, 0, input, output, NULL, NULL, NULL, NULL,
                            0.0f, 1e-8f, 0, scale_min,
                            scale_max, /* target range */
                            NULL, NULL, NULL, NULL);
}

/* ============================================================================
 * Vtable Auto-Fill Function: Install Normalization Wrappers
 * ========================================================================= */

/**
 * @brief Fill missing normalization entries in vtable from normalize_unified
 *
 * Called by fb_autofill_unified_to_specific() during plugin finalization.
 * Only installs wrappers for missing operations - doesn't overwrite existing
 * ones.
 */
void fb_autofill_normalization_from_unified(fb_backend_vtable_t *vtable) {
  if (!vtable || !vtable->normalize_unified) {
    return; /* No unified implementation available */
  }

  /* DNN Primitives - Batch Normalization */
  if (vtable->batch_norm_forward_training == NULL) {
    vtable->batch_norm_forward_training =
        fb_batch_norm_forward_training_from_unified;
  }
  if (vtable->batch_norm_forward_inference == NULL) {
    vtable->batch_norm_forward_inference =
        fb_batch_norm_forward_inference_from_unified;
  }
  if (vtable->batch_norm_backward == NULL) {
    vtable->batch_norm_backward = fb_batch_norm_backward_from_unified;
  }

  /* DNN Primitives - Layer Normalization */
  if (vtable->layer_norm_forward == NULL) {
    vtable->layer_norm_forward = fb_layer_norm_forward_from_unified;
  }
  if (vtable->layer_norm_backward == NULL) {
    vtable->layer_norm_backward = fb_layer_norm_backward_from_unified;
  }

  /* DNN Primitives - Instance/Group Normalization */
  if (vtable->instance_norm_forward == NULL) {
    vtable->instance_norm_forward = fb_instance_norm_forward_from_unified;
  }
  if (vtable->group_norm_forward == NULL) {
    vtable->group_norm_forward = fb_group_norm_forward_from_unified;
  }

  /* Statistics - Z-Score */
  if (vtable->stats_zscore == NULL) {
    vtable->stats_zscore = fb_stats_zscore_from_unified;
  }
  if (vtable->stats_modified_zscore == NULL) {
    vtable->stats_modified_zscore = fb_stats_modified_zscore_from_unified;
  }

  /* Preprocessing - Normalization Operations */
  if (vtable->standardize == NULL) {
    vtable->standardize = fb_standardize_from_unified;
  }
  if (vtable->normalize == NULL) {
    vtable->normalize = fb_normalize_from_unified;
  }
  if (vtable->min_max_scale == NULL) {
    vtable->min_max_scale = fb_min_max_scale_from_unified;
  }
}

#endif /* FB_EXTENDED_VTABLE_SUPPORT */